entries[30311] = { ["name"] = "Warpschnitter", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Einhändig Schwert\n248 - 461 Schaden Tempo 2.90\n(122.24 Schaden pro Sekunde)\n+35 Ausdauer\nHaltbarkeit 125 / 125\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 25.\nAnlegen: Erhöht die Angriffskraft um 70.\nTrefferchance: Erhöht 30 Sek. lang das Bewegungstempo um 50% und das Nahkampfangriffstempo um 20%." }
entries[30312] = { ["name"] = "Klinge der Unendlichkeit", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Einhändig Dolch\n171 - 318 Schaden Tempo 2.00\n(122.25 Schaden pro Sekunde)\n+35 Ausdauer\nHaltbarkeit 95 / 95\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 25.\nAnlegen: Erhöht die Angriffskraft um 70.\nTrefferchance: Erhöht den vom Ziel erlittenen Zauberschaden um 5% und bannt bei einem Treffer mit einer Nahkampffähigkeit Kael'thas' Fähigkeit 'Gedankenkontrolle'. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an." }
entries[30313] = { ["name"] = "Stab der Auflösung", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Zweihändig Stab\n131 - 309 Schaden Tempo 2.80\n(78.57 Schaden pro Sekunde)\n+75 Ausdauer\n+50 Intelligenz\nHaltbarkeit 145 / 145\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Zaubertrefferwertung um 75.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 325.\nAnlegen: Erhöht die Angriffskraft in Katzengestalt, Bärengestalt, Terrorbärengestalt oder Mondkingestalt um 1459.\nBenutzen: Umgibt verbündete Ziele in einem Umkreis von 30 Metern mit einem mentalen Schutzfeld, wodurch die Betroffenen immun gegen Betäubungs-, Schweige- und Desorientierungseffekte werden." }
