entries[31354] = { ["name"] = "Rezept: Fläschchen der Titanen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\nBenötigt Die Sha'tar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der Titanen.\nVerkaufspreis:\nFläschchen der Titanen\nBenötigt Stufe 50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 2 Stunden lang um 400. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut (7), Steinschuppenöl (3), Schwarzer Lotus , Kristallphiole" }
entries[31355] = { ["name"] = "Rezept: Fläschchen der obersten Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\nBenötigt Hüter der Zeit\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der obersten Macht.\nVerkaufspreis:\nFläschchen der obersten Macht\nBenötigt Stufe 50\nBenutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Bergsilbersalbei (3), Schwarzer Lotus , Kristallphiole" }
entries[31356] = { ["name"] = "Rezept: Fläschchen der destillierten Weisheit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\nBenötigt Expedition des Cenarius\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der destillierten Weisheit.\nVerkaufspreis:\nFläschchen der destillierten Weisheit\nBenötigt Stufe 50\nBenutzen: Erhöht die Intelligenz 2 Stunden lang um 65. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Eiskappe (3), Schwarzer Lotus , Kristallphiole" }
entries[31357] = { ["name"] = "Rezept: Fläschchen des chromatischen Widerstands", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (300)\nBenötigt Unteres Viertel\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens des chromatischen Widerstands.\nVerkaufspreis:\nFläschchen des chromatischen Widerstands\nBenötigt Stufe 50\nBenutzen: Erhöht den Widerstand gegen alle Arten von Magie 2 Stunden lang um 25. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Eiskappe (7), Bergsilbersalbei (3), Schwarzer Lotus , Kristallphiole" }
entries[31358] = { ["name"] = "Vorlage: Dämmersteinkrebs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (370)\nBenötigt Thrallmar\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Dämmersteinkrebses.\nVerkaufspreis:\nFigur - Dämmersteinkrebs\nWird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 70\nBenötigt Juwelenschleifen (350)\nAnlegen: Erhöht die Verteidigungswertung um 32.\nBenutzen: Erhöht die Ausweichwertung 20 Sek. lang um 125. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Khoriumbarren (4), Dämmerstein (2), Golddraenit (4)" }
entries[31359] = { ["name"] = "Vorlage: Robuster Tiefenperidot", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (315)\nBenötigt Thrallmar\n- Freundlich\nBenutzen: Lehrt Euch das Schleifen eines robusten Tiefenperidots.\nVerkaufspreis:\nRobuster Tiefenperidot\n+3 Verteidigungswertung und +4 Ausdauer\n\"Am besten für einen gelben oder blauen Sockel geeignet.\"\nVerkaufspreis:\nBenötigt Tiefenperidot" }
entries[31360] = { ["name"] = "Unfertiges Kopfstück", ["text"] = "Questgegenstand\nEinzigartig\nSchmuck\nBenötigt Stufe 67\nAnlegen: Ermöglicht es dem Träger Echos der Vergangenheit zu sehen.\nBenutzen: Unfertiges Kopfstück mit der Essenz von Gul'dan erfüllen." }
entries[31361] = { ["name"] = "Muster: Kobrahautbeinrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (335)\nBenötigt Thrallmar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung einer Kobrahautbeinrüstung.\nVerkaufspreis:\nKobrahautbeinrüstung\nBenötigt Stufe 60\nBenutzen: Eine Hose dauerhaft mit einer Kobrahautrüstung verstärken, sodass die Angriffskraft um 40 und die kritische Trefferwertung um 10 erhöht wird.\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Kobraschuppen (2), Urluft (4)" }
entries[31362] = { ["name"] = "Muster: Netherkobrabeinrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (365)\nBenötigt Thrallmar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Netherkobrabeinrüstung.\nVerkaufspreis:\nNetherkobrabeinrüstung\nBenötigt Stufe 60\nBenutzen: Eine Hose dauerhaft mit einer Netherkobrarüstung verstärken, sodass die Angriffskraft um 50 und die kritische Trefferwertung um 12 erhöht wird.\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Kobraschuppen (4), Urluft (8), Urnether" }
